         'order' => 'DESC'
      ), $atts );

      // HTML structure
      $html = '';

      $html .= '<div class="cw-enhancements-services-list">';

      // Query services posts
      $services_args = array(
         'post_type'      => 'services',
         'posts_per_page' => $a['limit'],
         'orderby'        => $a['orderby'],
         'order'          => $a['order']
      );

      // If needed, customize query based on shortcode attributes (e.g., Custom ordering with a specific category)
      // ...

      $services_query = new WP_Query( $services_args );

      if ($services_query->have_posts()) :

         $html .= '<ul>';

         while ($services_query->have_posts()) :

            $services_query->the_post();
            $service = get_post();

            $html .= '<li>';
            $html .= '<h3>';
            $html .= esc_html( $service->post_title );
            $html .= '</h3>';
            $html .= wpautop( get_the_excerpt() );
            $html .= '</li>';

         endwhile;

         wp_reset_postdata();

         $html .= '</ul>';

      else :

         $html .= '<p>' . __( 'No services available.' ) . '</p>';

      endif;

      $html .= '</div>';

      return $html;

   }

