```
using System;

namespace PlanckConstantPhotonEnergy
{
    class Program
    {
        static void Main(string[] args)
        {
            double wavelength = 600 * Math.Pow(10, -9); //convert nm to meters
            double speedOfLight = 299792458;

            double planckConstant = 6.62607004 * Math.Pow(10, -34);
            double energy = (planckConstant * speedOfLight) / wavelength; //calculate energy using Planck's constant (h) and speed of light

            double h = energy / speedOfLight;

            Console.WriteLine("The value of Planck's constant (h) is: " + h.ToString() + " J s");
            Console.WriteLine("The energy of a photon with a wavelength of 600 nm is: " + energy.ToString() + " J");
        }
    }
}
```

Note: The value of Planck's constant (h) is fixed and does not change in this calculation. Since we're using the value of energy (calculated using h and c) divided by c to find h, we end up with a result for h that is very small (in the order of 10^-34 J*s). To avoid displaying a large number in scientific notation, we specifically format the output for h to display as "J s".

