   ```

2. Initialize a new TypeScript project with `tsc --init`

   - This will create a `tsconfig.json` file with default settings

3. Create a new directory for your application and navigate inside

   ```
   mkdir my-app && cd $_
   ```

4. Install Express, a few necessary dependencies, and TypeScript type definitions.

   ```
   npm install express express-serve-static-core serve-static @types/express @types/node --save-dev
   ```

5. Create a file named `server.ts`

   ```
   touch server.ts
   ```

6. Open or create a `tsconfig.json` file in the root directory and configure it to enable support for the `Node.js` module resolution, `import` declarations, and target the execution environment:

   ```json
   {
     "compilerOptions": {
       "module": "CommonJS",
       "esModuleInterop": true,
       "target": "ES2017",
       "noImplicitAny": true,
       "moduleResolution": "node",
       "sourceMap": true,
       "outDir": "./dist",
       "strict": true,
       "resolveJsonModule": true,
       "skipLibCheck": true
     },
     "include": ["./src"],
     "exclude": ["node_modules", "dist"]
   }
   ```

   - The `module` option is set to `"CommonJS"` for Node.js compatibility and `"esModuleInterop"` is enabled to allow importing from non-TypeScript modules.
   - The `target` option is set to `"ES2017"`, which is supported by Node.js version 8.0 and later.
   - The `moduleResolution` option is set to `"node"`, which enables support for the Node.js module resolution.
   - The `include` and `exclude` options are used to tell TypeScript which files to compile.

7. In the `server.ts` file, write the following code:

   ```typescript
   import express, { Application } from 'express';
   import * as helmet from 'helmet';
   import * as bodyParser from 'body-parser';
   import { urlencoded } from 'body-parser';
   import { routes } from './routes';

   const app: Application = express();

   // Set security HTTP headers
   app.use(helmet());

   // Use body parser middleware
   app.use(urlencoded({ extended: true }));
   app.use(bodyParser.json());

   // Mount routes
   routes(app);

   // Start server
   const PORT: number = Number(process.env.PORT || 3000);

   app.listen(PORT, () => {
     console.log(`Server listening on port ${PORT}!`);
   });
   ```

