from itertools import accumulate

class SegregatedIntervalTree:
    def __init__(self):
        self.root = None

    def _count(self, node):
        return node.count if node else 0

    def _is_even_node(self, node):
        return bool(node) and not node.value % 2

    def enqueue(self, val):
        if not self.root:
            self.root = self._create_odd_node(val, self._count(self.root) if self.root else 0)
        else:
            curr = self.root
            while True:
                if self._is_even_node(curr):
                    curr.left = self._create_odd_node(val, curr.count // 2 + 1)
                    curr = curr.left
                elif curr.right:
                    curr = curr.right
                else:
                    curr.right = self._create_unbalanced_node()
                    curr = curr.left

    def dequeue(self):
        if not self.root:
            return None

        root_val = self.root.value
        if not self.root.left:
            self.root = self.root.right
        else:
            if self.root.right:
                self.root.left, self.root.right = self.root.right, self.root.left
            self.root = self.root.left

        return root_val

    def see_saw(self):
        if not self.root:
            return 0

        def _product(node):
            if self._is_even_node(node):
                return node.value / _product(node.left)
            else:
                return node.value + _product(node.right)

        return _product(self.root)

    def _count_balanced(self, node):
        return max(self._count(node.left), self._count(node.right))

    def _create_even_node(self, val):
        node = collections.defaultdict(int)
        node['value'] = val
        node['count'] = (self._count_balanced(self.root) + 1) // 2
        return node

    def _create_odd_node(self, val, count):
        node = collections.defaultdict(int)
        node['value'] = val
        node['count'] = count
        return node

    def _create_unbalanced_node(self):
        node = collections.defaultdict(int)
        return node
