    schema: [],
    messages: {
      mutationDetected: `Updated lifecycle hook method {{method}} 
        directly or indirectly mutates internal component state.`,
      mutationThroughCallDetected: `Method call {{methodName}} 
        mutates internal component state indirectly through method {{method}}.`,
    },
    recommends: ['vue/no-change-v-model', 'vue/no-parsing-error'],
  },
