      return (
        rules.lifecycleKeys.some(key => {
          return key.some(scope =>
            currentScope.getScope(.ScopesEnvironmentScope).hasOwnIdentifier(
              scope
            )
          );
        }) &&
        rules.propertyNames.some(key => key.includes(node.property.name))
      );
    }

    function getMemberExpression(node) {
      while (node.type !== 'MemberExpression') {
        if (node.type === 'Identifier') {
          break;
        }
        node = getNode(node);
      }

      return node;
    }

