      const sourceCode = getSourceCode(context);
      return sourceCode.getText(node).length;
    }

    function getMethodName(node) {
      return getMemberExpression(node).property.name;
    }

    function getCallingMemberName(callExp) {
      const methodName = getMemberExpression(callExp.callee).property.name;
      const methodArgs = callExp.arguments;
