  };
}

// helper functions

function isValidComponent(node: any): boolean {
  return node.type === 'VueTemplate' || node.type === 'VueComponent';
}

function isLifecycleHook(node: any): boolean {
  return node.type === 'VueLifecycleHooks';
}

function getMethodDeclaration(node: any): any {
  return node.body.find((child: any) => child.type === 'MethodDefinition');
}

function isMethodMutation(node: any): boolean {
  // check if method body mutates internal component state
  const methodBody = node.body.body;
  if (!methodBody) {
    return false;
  }
  const mutationsExist = methodBody.some(prop => {
    if (prop.type === 'MemberExpression') {
      const property = prop.object;
      // if property references a reactive data property
      if (property.type === 'MemberExpression' && property.object.type === 'ThisExpression') {
        const propertyPath = property.property.name;
        // check if the data property is being set
        return prop.property.type === 'AssignmentPattern' && prop.property.left.name === propertyPath;
      }
    }
    return false;
  });

  // recursively check if called methods mutate internal state
  const methodCalls = node.utilityarahasi.body.filter(call => call.type === 'CallExpression');
  if (methodCalls.some(call => {
    const callee = call.callee;
    const calledMethod = callee.object && getMethodDeclaration(callee.object) || callee.type === 'Identifier';
    if (calledMethod && calledMethod.type === 'MethodDefinition') {
      return isMethodMutation(callee);
    }
    return false;
  })) {
    return true;
  }

  return mutationsExist;
}

