  const TrackMethodsInLifecycleHook = (node) => {
    const { body } = node;

    if (!body) {
      return;
    }

    body.body.forEach((statement) => {
      if (statement.type === 'ExpressionStatement') {
        trackPropertiesInExpression(statement.expression);
      }
    });
  };

  const TrackCallsToMethodsInLifecycleHook = (node) => {
    node.body.forEach((statement) => {
      if (statement.type === 'ExpressionStatement') {
        const { arguments } = statement.expression;

        if (arguments.length > 0) {
          trackMethodBeingCalled(arguments[0]);
        }
      }
    });
  };
  ```

9. Write a helper function to determine whether a mutation takes place:

  ```javascript
  const isMutableOperation = (stmt) => {
    const { left, right } = stmt;

    // Assigning
    if (stmt.type === 'AssignmentExpression') {
      return true;
    }

    // Pushing
    if (
      stmt.type === 'CallExpression' &&
      left.type === 'MemberExpression' &&
      left.object.type === 'Identifier' &&
      left.object.name === 'this' &&
      right.type === 'ArrayExpression' &&
      right.elements.length === 1 &&
      right.elements[0].type === 'Identifier' &&
      vue.config.globalProperties.includes(right.elements[0].name) &&
      /^(push|splice)$/.test(right.elements[0].name)
    ) {
      return true;
    }

    return false;
  };
  ```

